import{_ as e,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"ShortcutsModal","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/shortcuts-modal.md","filePath":"workbench/shortcuts-modal.md"}'),r={name:"workbench/shortcuts-modal.md"};function s(h,t,c,i,l,n){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="shortcutsmodal" tabindex="-1">ShortcutsModal <a class="header-anchor" href="#shortcutsmodal" aria-label="Permalink to &quot;ShortcutsModal&quot;">​</a></h1><p>ShortcutsModal is the list of keyboard shortcuts, in a modal.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to open the list of keyboard shortcuts from a menu or a button, with the same shortcuts the application attaches. A <a href="./shell">Shell</a> already opens it with the help key and lists its <code>shortcuts</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether it is open (bindable)</td></tr><tr><td><code>shortcuts</code></td><td>required</td><td>The shortcuts, <code>{ key, label, group? }[]</code> (below)</td></tr><tr><td><code>title</code></td><td><code>keyboardShortcuts</code> message</td><td>The title of the modal</td></tr><tr><td><code>mac</code></td><td>the platform</td><td><code>true</code> writes the keys as a Mac does</td></tr><tr><td><code>groups</code></td><td></td><td>The order of the groups; the others follow as they first appear</td></tr><tr><td><code>onclose</code></td><td></td><td>Called when it closes</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow, for documentation</td></tr></tbody></table><p><code>key</code> is written as a Shell&#39;s shortcut is (<code>mod+z</code>), and <code>label</code> says what the shortcut does. <code>display</code> lists other keys in its place, each written as <code>key</code> is and joined with &quot; / &quot;; a <code>hidden</code> shortcut is not listed. A whole <code>Shortcut</code> can be passed; <code>run</code>, <code>when</code> and <code>aliases</code> are not read.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/modal">Modal</a> of the md width. The shortcuts without a group come first, as one <a href="./../components/list">List</a> without a heading; then each group is a <a href="./../components/section">Section</a> with the group as its title, in the order of <code>groups</code> and then in the order the groups first appear. Each shortcut is a <a href="./../components/list-item">ListItem</a> that is only read, with a line under it: the label on the left, clipped to one line, and the key on the right as a bare <a href="./../components/kbd">Kbd</a>, written as the platform writes it (⇧⌘Z on a Mac, Ctrl+Shift+Z elsewhere; <code>digit</code> as 0–9).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/shortcuts-modal/" title="ShortcutsModal" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/shortcuts-modal/" target="_blank" rel="noopener">ShortcutsModal</a></figcaption></figure>',11)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
